fn resolve_dim(v: &serde_json::Value, opts: &GraphOptions) -> usize {
    match v {
        serde_json::Value::Number(n) => {
        let v = n.as_u64().unwrap_or(0) as usize;
        if v == 0 { opts.sequence_length } else { v }
        },
        serde_json::Value::String(s) => match s.as_str() {
            "sequence_length" => opts.sequence_length,
            "num_samples" => opts.max_waveform_samples,
            "?" => opts.sequence_length,
            _ if s.starts_with("unk__") => opts.sequence_length,
            _ => 1,
        },
        _ => 1,
    }
}

fn map_spatial(v: usize, ref_v: usize, actual: usize) -> usize {
    if v == 0 || ref_v == 0 {
        return v;
    }
    if v == ref_v {
        return actual;
    }
    let mut r = ref_v;
    let mut a = actual;
    while r > 1 {
        if v == r + 1 {
            return a + 1;
        }
        if r % 2 != 0 {
            break;
        }
        r /= 2;
        a /= 2;
        if r == v {
            return a;
        }
    }
    v
}

fn shape_from_meta(meta: &serde_json::Value, opts: &GraphOptions) -> Shape {
    let obj = meta.as_object().expect("shape meta");
    let shape_v = obj.get("shape").expect("shape");
    let dtype_s = obj.get("dtype").and_then(|d| d.as_str()).unwrap_or("f32");
    let mut dims: Vec<usize> = match shape_v {
        serde_json::Value::Array(a) => a.iter().map(|d| resolve_dim(d, opts)).collect(),
        _ => vec![1],
    };
    // Remap NCHW spatial axes from the reference staticize size.
    // Rank-3: CTC [N,T,C] (large C), feature [N,C,W], or SVTR [N,T,C].
    if dims.len() == 4 {
        dims[2] = map_spatial(dims[2], 48, opts.height);
        dims[3] = map_spatial(dims[3], 160, opts.width);
    } else if dims.len() == 3 {
        // CTC logits [N,T,C] (large C): remap T.
        // Feature [N,C,W] (C often equals ref width, e.g. 160): remap W only.
        // SVTR [N,T,C] (moderate C): remap T when W-axis does not move.
        if dims[2] > 1000 {
            dims[1] = map_spatial(dims[1], 160, opts.width);
        } else {
            let last_w = map_spatial(dims[2], 160, opts.width);
            let mid_w = map_spatial(dims[1], 160, opts.width);
            if last_w != dims[2] {
                dims[2] = last_w;
            } else if mid_w != dims[1] {
                dims[1] = mid_w;
            }
        }
    }
    let dtype = match dtype_s {
        "f32" => DType::F32,
        "i64" => DType::I64,
        "i32" => DType::I32,
        "bool" => DType::Bool,
        _ => DType::F32,
    };
    Shape::new(&dims, dtype)
}

/// Channel axis: the dimension of `like` whose size matches the rank-1 param length.
fn channel_axis_for_param(m: &mut HirMut, param: HirNodeId, like: HirNodeId) -> usize {
    let c = m.shape(param).dim(0).unwrap_static();
    let like_sh = m.shape(like);
    for (i, d) in like_sh.dims().iter().enumerate() {
    if d.unwrap_static() == c { return i; }
    }
    if like_sh.rank() >= 2 { like_sh.rank() - 1 } else { 0 }
}

/// Reshape a rank-1 scale/bias vector for channel-wise broadcast on `like`.
fn broadcast_1d_param(m: &mut HirMut, param: HirNodeId, like: HirNodeId, axis: usize) -> HirNodeId {
    let rank = m.shape(like).rank().max(1);
    let c = m.shape(param).dim(0).unwrap_static() as i64;
    let mut bc = vec![1i64; rank];
    bc[axis.min(rank.saturating_sub(1))] = c;
    m.reshape_(param, bc)
}

fn broadcast_param_channels(m: &mut HirMut, param: HirNodeId, like: HirNodeId) -> HirNodeId {
    let axis = channel_axis_for_param(m, param, like);
    broadcast_1d_param(m, param, like, axis)
}

fn inst_norm_reduce_axes(rank: usize, channel_axis: usize) -> Vec<usize> {
    (0..rank).filter(|&i| i != 0 && i != channel_axis).collect()
}

fn binary_infer(m: &mut HirMut, op: BinaryOp, a: HirNodeId, b: HirNodeId, _site: &str) -> HirNodeId {
    binary_infer_inner(m, op, a, b)
}

fn binary_infer_inner(m: &mut HirMut, op: BinaryOp, a: HirNodeId, b: HirNodeId) -> HirNodeId {
    let mut a_in = a;
    let mut b_in = b;
    let sa0 = m.shape(a_in).clone();
    let sb0 = m.shape(b_in).clone();
    if (sa0.rank() == 0 || sa0.rank() == 1) && sb0.rank() >= 2 {
      let a1 = if sa0.rank() == 0 { m.reshape_(a_in, vec![1]) } else { a_in };
      a_in = broadcast_param_channels(m, a1, b_in);
    } else if (sb0.rank() == 0 || sb0.rank() == 1) && sa0.rank() >= 2 {
      let b1 = if sb0.rank() == 0 { m.reshape_(b_in, vec![1]) } else { b_in };
      b_in = broadcast_param_channels(m, b1, a_in);
    }
    let sa = m.shape(a_in).clone();
    let sb = m.shape(b_in).clone();
    if let Ok(sh) = shape::binary_shape(&sa, &sb) {
      return m.add_node(rlx_ir::Op::Binary(op), vec![a_in, b_in], sh);
    }
    // Special case: flatten([B,C,L]) -> [B,1,C*L] then add per-channel bias [1,1,C].
    if sa.rank() == 3 && sb.rank() == 3
      && sa.dim(1).unwrap_static() == 1
      && sb.dim(0).unwrap_static() == 1
      && sb.dim(1).unwrap_static() == 1
      && sa.dim(2).unwrap_static() % sb.dim(2).unwrap_static() == 0 {
      let bsz = sa.dim(0).unwrap_static();
      let c = sb.dim(2).unwrap_static();
      let l = sa.dim(2).unwrap_static() / c;
      let dt = sa.dtype();
      let a3 = m.reshape_(a_in, vec![bsz as i64, c as i64, l as i64]);
      let b3 = m.reshape_(b_in, vec![1, c as i64, 1]);
      let y3 = m.add_node(rlx_ir::Op::Binary(op), vec![a3, b3], Shape::new(&[bsz, c, l], dt));
      return m.reshape_(y3, vec![bsz as i64, 1, (c * l) as i64]);
    }
    // Special case: [B,2C,L] + [B,C,L] (concat-style broadcast).
    if sa.rank() == sb.rank() && sa.rank() == 3
      && sa.dim(0).unwrap_static() == sb.dim(0).unwrap_static()
      && sa.dim(2).unwrap_static() == sb.dim(2).unwrap_static()
      && sa.dim(1).unwrap_static() == 2 * sb.dim(1).unwrap_static() {
      let bsz = sa.dim(0).unwrap_static();
      let c = sb.dim(1).unwrap_static();
      let l = sa.dim(2).unwrap_static();
      let dt = sa.dtype();
      let b_rep = m.reshape_(b_in, vec![bsz as i64, c as i64, 1, l as i64]);
      let b_rep = m.add_node(rlx_ir::Op::Concat { axis: 3 }, vec![b_rep.clone(), b_rep], Shape::new(&[bsz, c, 2, l], dt));
      b_in = m.reshape_(b_rep, vec![bsz as i64, (2 * c) as i64, l as i64]);
      let sh = shape::binary_shape(m.shape(a_in), m.shape(b_in)).unwrap_or(sa.clone());
      return m.add_node(rlx_ir::Op::Binary(op), vec![a_in, b_in], sh);
    }
    let sh = if sa.rank() >= sb.rank() { sa } else { sb };
    m.add_node(rlx_ir::Op::Binary(op), vec![a_in, b_in], sh)
}

fn hir_erf(b: &mut Builder, x: HirNodeId, site: &str) -> HirNodeId {
    let s = { let m = HirMut::new(&mut b.hir); m.shape(x).clone() };
    let sc = |b: &mut Builder, tag: &str, v: f32| -> HirNodeId {
      let key = format!("__erf_{tag}__/{site}");
      b.bind_param(&key, &[1], vec![v])
    };
    let one = sc(b, "one", 1.0);
    let p = sc(b, "p", 0.327_591_1);
    let a5 = sc(b, "a5", 1.061_405_4);
    let a0 = sc(b, "a0", -1.453_152_1);
    let a1 = sc(b, "a1", 1.421_413_8);
    let a2 = sc(b, "a2", -0.284_496_72);
    let a3 = sc(b, "a3", 0.254_829_6);
    let tiny = sc(b, "tiny", 1e-20);
    let mut m = HirMut::new(&mut b.hir);
    let ax = m.add_node(rlx_ir::Op::Activation(Activation::Abs), vec![x], s.clone());
    let pax = m.add_node(rlx_ir::Op::Binary(BinaryOp::Mul), vec![ax, p], s.clone());
    let denom = m.add_node(rlx_ir::Op::Binary(BinaryOp::Add), vec![pax, one], s.clone());
    let t = m.add_node(rlx_ir::Op::Binary(BinaryOp::Div), vec![one, denom], s.clone());
    let mut acc = a5;
    for coef in [a0, a1, a2, a3] {
      let tm = m.add_node(rlx_ir::Op::Binary(BinaryOp::Mul), vec![t, acc], s.clone());
      acc = m.add_node(rlx_ir::Op::Binary(BinaryOp::Add), vec![tm, coef], s.clone());
    }
    let poly = m.add_node(rlx_ir::Op::Binary(BinaryOp::Mul), vec![t, acc], s.clone());
    let x2 = m.add_node(rlx_ir::Op::Binary(BinaryOp::Mul), vec![x, x], s.clone());
    let negx2 = m.add_node(rlx_ir::Op::Activation(Activation::Neg), vec![x2], s.clone());
    let ex = m.add_node(rlx_ir::Op::Activation(Activation::Exp), vec![negx2], s.clone());
    let pe = m.add_node(rlx_ir::Op::Binary(BinaryOp::Mul), vec![poly, ex], s.clone());
    let y = m.add_node(rlx_ir::Op::Binary(BinaryOp::Sub), vec![one, pe], s.clone());
    let x2t = m.add_node(rlx_ir::Op::Binary(BinaryOp::Add), vec![x2, tiny], s.clone());
    let inv = m.add_node(rlx_ir::Op::Activation(Activation::Rsqrt), vec![x2t], s.clone());
    let sign = m.add_node(rlx_ir::Op::Binary(BinaryOp::Mul), vec![x, inv], s.clone());
    m.add_node(rlx_ir::Op::Binary(BinaryOp::Mul), vec![sign, y], s)
}